// Build and pack the project from two different clean dependency installs and
// checkout paths, then compare every generated byte. The locked toolchain and
// printed manifest digest let another party reproduce the same artifact from
// the same commit instead of trusting one maintainer's dependency tree.

import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { cp, mkdtemp, readFile, readdir, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { basename, dirname, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const scratch = await mkdtemp(join(tmpdir(), 'jsonloupe-repeatable-'));
const generated = ['dist', 'dist-cli', 'dist-mcp'];
const skipped = new Set(['.git', 'coverage', 'dist', 'dist-cli', 'dist-mcp', 'node_modules']);
const skippedFiles = new Set(['.api-key', '.anthropic-key', '.DS_Store']);

function npm(cwd, ...args) {
  return execFileSync(process.platform === 'win32' ? 'npm.cmd' : 'npm', args, {
    cwd,
    encoding: 'utf8',
    env: {
      ...process.env,
      LANG: 'C',
      LC_ALL: 'C',
      SOURCE_DATE_EPOCH: '0',
      TZ: 'UTC',
      npm_config_cache: join(scratch, 'npm-cache'),
    },
    maxBuffer: 10 * 1024 * 1024,
  });
}

async function filesUnder(directory, prefix = '') {
  const entries = await readdir(directory, { withFileTypes: true });
  const files = [];
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const path = join(directory, entry.name);
    const name = prefix ? `${prefix}/${entry.name}` : entry.name;
    if (entry.isDirectory()) files.push(...await filesUnder(path, name));
    else if (entry.isFile()) files.push({ name, path });
  }
  return files;
}

async function digest(path) {
  return createHash('sha256').update(await readFile(path)).digest('hex');
}

async function build(run) {
  const checkout = join(scratch, run);
  await cp(root, checkout, {
    recursive: true,
    filter(source) {
      const local = relative(root, source);
      if (local === '') return true;
      const first = local.split(sep)[0];
      return !skipped.has(first)
        && !skippedFiles.has(first)
        && !first.startsWith('.env')
        && !first.endsWith('.tgz');
    },
  });
  npm(checkout, 'ci', '--ignore-scripts', '--no-audit', '--no-fund');
  npm(checkout, 'run', 'build');

  const manifest = new Map();
  for (const output of generated) {
    for (const file of await filesUnder(join(checkout, output), output)) {
      manifest.set(file.name, await digest(file.path));
    }
  }

  const packed = JSON.parse(npm(checkout, 'pack', '--ignore-scripts', '--json'));
  const packageName = packed[0]?.filename;
  if (typeof packageName !== 'string') throw new Error(`npm pack returned no filename for ${run}`);
  manifest.set(packageName, await digest(join(checkout, basename(packageName))));
  return manifest;
}

try {
  const packageJson = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'));
  const expectedNode = packageJson.devEngines?.runtime?.version;
  const expectedNpm = packageJson.devEngines?.packageManager?.version;
  const actualNpm = npm(root, '--version').trim();
  if (process.versions.node !== expectedNode || actualNpm !== expectedNpm) {
    throw new Error(
      `reproducible build requires Node ${expectedNode} and npm ${expectedNpm}; ` +
      `found Node ${process.versions.node} and npm ${actualNpm}`,
    );
  }
  const first = await build('first');
  const second = await build('second');
  const names = new Set([...first.keys(), ...second.keys()]);
  const changed = [...names].filter((name) => first.get(name) !== second.get(name));
  if (changed.length) {
    for (const name of changed) {
      console.error(`${name}: ${first.get(name) ?? 'missing'} != ${second.get(name) ?? 'missing'}`);
    }
    throw new Error(`${changed.length} generated file${changed.length === 1 ? '' : 's'} differed between clean paths`);
  }
  const manifest = [...first.entries()]
    .sort(([left], [right]) => left.localeCompare(right))
    .map(([name, hash]) => `${hash}  ${name}`)
    .join('\n');
  const manifestHash = createHash('sha256').update(manifest).digest('hex');
  console.log(`reproducible build: ${names.size} generated files matched byte-for-byte`);
  console.log(`toolchain: Node ${process.versions.node}, npm ${actualNpm}`);
  console.log(`manifest sha256: ${manifestHash}`);
} finally {
  await rm(scratch, { recursive: true, force: true });
}
